function buildSettings({ prefix, os, platform, topics, defaultVariants }) {
  return topics.flatMap((topic) => (topic.variants || defaultVariants).map((variant) => {
    const title = `${platform}で${topic.title}（${variant.label}）`;
    const version = topic.version || VERSION[os];
    const steps = (topic.steps || STEPS.app).map((step) => step.replaceAll("{focus}", variant.label));
    return {
      title,
      slug: `${prefix}-${topic.id}-${variant.id}`,
      os,
      version,
      category: "troubleshoot",
      aliases: [`${variant.label}の${topic.alias}`, `${platform} ${topic.alias}`],
      path: topic.path,
      steps,
      related_slugs: [],
      keywords: [platform, topic.alias, ...topic.keywords, ...variant.keywords],
      description: `${variant.label}で${topic.alias}が起きたときの確認手順です。`,
      difficulty: topic.difficulty || "beginner",
      estimate_minutes: topic.estimate_minutes || 6,
      verified_at: VERIFIED_AT,
      review_due_at: REVIEW_DUE_AT,
      source_url: topic.source,
      device_scope: `${version}を基準にした一般的な対処です。機種・アプリのバージョン・管理者設定で表示や手順が異なる場合があります。`,
      impact: `${variant.label}の環境を確認し、${topic.alias}の原因を切り分けられる可能性があります。`,
      ...(topic.caution ? { caution: topic.caution } : {}),
      editor_note: "公式サポートを参照して作成した下書き候補です。公開前に実機・アプリ版で表示と手順を確認してください。",
    };
  }));
}

